    print('• muddatli sotuv')
    pg.click('.tabbar [data-tab=own]'); pg.click('.acc-card'); pg.wait_for_selector('[data-act=do-sell]'); pg.click('[data-act=do-sell]'); pg.wait_for_selector('input[name=sold_price]')
    ok(pg.query_selector('input[name=inst]') is not None,'«Muddatli to\'lov» belgisi bor')
