    pg.fill('input[name=inst_start]','2026-11-01'); pg.fill('input[name=inst_end]','2027-01-30'); pg.fill('input[name=inst_parts]','3'); pg.fill('input[name=inst_first]','300000'); pg.wait_for_timeout(300)
    ok('3 qism' in pg.inner_text('#inst-preview'),'ko\'rib chiqish: '+pg.inner_text('#inst-preview')); pg.screenshot(path=f'{shots}/50-sell-inst.png')
    pg.click('.sheet-wrap:last-of-type button[type=submit]'); pg.wait_for_timeout(1000)
    a=pg.evaluate("window.__mock.accounts[0]"); ok(a['inst_on'] and a['inst_parts']==3 and a['inst_end']=='2027-01-30','reja saqlandi')
    ok(len(pg.evaluate("window.__mock.payments"))==1 and pg.evaluate("window.__mock.payments[0].amount")==300000,'boshlang\'ich to\'lov yozildi')
    print('• muddatli to\'lov oynasi')
    pg.click('.tabbar [data-tab=sold]'); pg.wait_for_timeout(300); pg.click('.acc-card'); pg.wait_for_selector('#inst-card-host .inst-card'); pg.wait_for_timeout(300)
    t=pg.inner_text('#inst-card-host').replace('\xa0',' '); ok('600 000' in t,'karta: qoldi 600 000 -> '+t.replace('\n',' | ')[:120]); pg.screenshot(path=f'{shots}/51-detail-inst.png')
