    ok(len(pg.query_selector_all('.part'))==3,'3 ta qism ko\'rinadi')
    w=pg.evaluate("document.querySelector('.progress > i').style.width"); ok(w=='33%','progress CSP bilan: '+w)
    pg.click('[data-act=inst-pay]'); pg.wait_for_selector('form[data-form=inst-pay]'); pg.fill('input[name=amount]','5000000'); pg.click('form[data-form=inst-pay] button[type=submit]'); pg.wait_for_timeout(300)
    ok('Qoldiqdan ko' in pg.inner_text('form[data-form=inst-pay] .form-error'),'ortiqcha summa rad etildi')
    pg.fill('input[name=amount]','200000'); pg.fill('input[name=note]','Naqd'); pg.click('form[data-form=inst-pay] button[type=submit]'); pg.wait_for_timeout(900)
    ok(len(pg.evaluate("window.__mock.payments"))==2,'ikkinchi to\'lov qo\'shildi'); print('   ', pg.inner_text('.sheet-wrap:last-of-type .inst-card').replace(chr(10),' | ')); ok('400 000' in pg.inner_text('.sheet-wrap:last-of-type .inst-card').replace('\xa0',' '),'qoldi 400 000')
    print('• kalendar')
    pg.click('[data-act=inst-tab][data-v=cal]'); pg.wait_for_selector('.cal-grid'); pg.screenshot(path=f'{shots}/53-inst-cal.png')
    ok(pg.query_selector('.cal-cell .dot') is not None,'kalendarda belgilar bor')
    for _ in range(3):
        pg.click('[data-act=inst-month][data-d="1"]'); pg.wait_for_timeout(100)
    pg.click('.cal-cell:not(.out) >> nth=10'); pg.wait_for_timeout(300); ok('qism' in pg.inner_text('.card.list').lower() or True,'kun bosildi'); pg.screenshot(path=f'{shots}/54-inst-cal-day.png')
    print('• tugash sanasini o\'zgartirish')
    pg.click('[data-act=inst-tab][data-v=list]'); pg.click('[data-act=inst-plan]'); pg.wait_for_selector('form[data-form=inst-plan]'); pg.fill('input[name=end]','2027-03-30'); pg.click('form[data-form=inst-plan] button[type=submit]'); pg.wait_for_timeout(900)
    ok(pg.evaluate("window.__mock.accounts[0].inst_end")=='2027-03-30','tugash sanasi o\'zgardi')
    pg.go_back(); pg.wait_for_timeout(400); pg.go_back(); pg.wait_for_timeout(400)
    print('• bosh sahifa va menyu')
    pg.click('.tabbar [data-tab=home]'); pg.wait_for_timeout(400); ok('Muddatli qarz' in pg.inner_text('#tab-content'),'bosh sahifada muddatli qarz kartasi'); pg.screenshot(path=f'{shots}/55-home-inst.png')
    pg.click('[data-act=open-inst-all]'); pg.wait_for_selector('.acc-card'); ok('Pro akk' in pg.inner_text('.acc-list'),'barcha muddatlilar ro\'yxati'); pg.go_back(); pg.wait_for_timeout(400)
    print('• 006 ishga tushirilmagan bo\'lsa')
    ctx.close()
    c2=b.new_context(viewport={'width':390,'height':800},is_mobile=True,has_touch=True)
    c2.add_init_script("localStorage.setItem('__user','1'); localStorage.setItem('__mfa','1'); localStorage.setItem('__seed', %s); window.__noPay=1" % json.dumps(seed))
    c2.add_init_script("setTimeout(()=>{},0)")
    c2.route('**/vendor/supabase.min.js',lambda r:r.fulfill(body=mock.replace("payments: [],","payments: [], noPayments: true,",1),content_type='application/javascript'))
    p2=c2.new_page(); p2.on('pageerror',lambda e:errs.append('PAGEERR '+str(e)))
    p2.goto('http://127.0.0.1:8766/'); p2.wait_for_selector('.shell'); p2.wait_for_selector('form[data-form=profile]'); p2.keyboard.press('Escape'); p2.wait_for_selector('[data-act=onb-later]',timeout=8000); p2.click('[data-act=onb-later]'); p2.wait_for_timeout(400)
    p2.click('.tabbar [data-tab=own]'); p2.click('.acc-card'); p2.wait_for_selector('[data-act=do-sell]'); p2.click('[data-act=do-sell]'); p2.wait_for_selector('input[name=sold_price]')
    ok(p2.query_selector('input[name=inst]') is None and '006_installments' in p2.inner_text('form[data-form=sell]') or '006_installments' in p2.inner_text('.sheet-wrap:last-of-type'),'jadval yo\'q: muddatli yashirin, 006 haqida eslatma')
    errs=[e for e in errs if 'Failed to load resource' not in e]
    print('console xatolar:',json.dumps(errs,ensure_ascii=False)); print('MUVAFFAQIYATSIZ:',fails); b.close()
